package dualsense

import (
	"encoding/binary"
	"os"
	"testing"
)

// Optional cross-language fixture generated by the real C# rear mapper/report
// builder. It exercises the existing backend without Windows or a USB driver.
func TestMappedTouchGestureWire(t *testing.T) {
	path := os.Getenv("PRO2_TOUCH_WIRE_FIXTURE")
	if path == "" {
		t.Skip("C# touch gesture fixture not supplied")
	}
	wire, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if len(wire) != 7*70*InputStateSize {
		t.Fatalf("unexpected fixture length %d", len(wire))
	}
	d := &DualSense{}
	starts, lifts := 0, 0
	active := false
	for i := 0; i < 7*70; i++ {
		var state InputState
		packet := wire[i*InputStateSize : (i+1)*InputStateSize]
		if err := state.UnmarshalBinary(packet); err != nil {
			t.Fatal(err)
		}
		if state.Touch1Active && !active {
			starts++
		}
		if !state.Touch1Active && active {
			lifts++
		}
		active = state.Touch1Active
		report := d.buildUSBInputReportAt(&state, &MetaState{}, uint64(i)*7500)
		if len(report) != 64 || report[0] != 1 {
			t.Fatal("native USB report shape changed")
		}
		x := uint16(report[34]) | uint16(report[35]&0x0f)<<8
		y := uint16(report[35]>>4) | uint16(report[36])<<4
		if x != state.Touch1X || y != state.Touch1Y || (report[33]&0x80 == 0) != state.Touch1Active {
			t.Fatalf("touch lost between API and USB frame %d: (%d,%d) %02x", i, x, y, report[33])
		}
		if report[37]&0x80 == 0 || state.Touch2Active {
			t.Fatal("unexpected second finger")
		}
		if report[10]&2 != 0 {
			t.Fatal("finger motion must not synthesize touchpad click")
		}
		if binary.LittleEndian.Uint16(report[16:18]) != binary.LittleEndian.Uint16(packet[21:23]) {
			t.Fatal("touch modified gyro data")
		}
	}
	if starts != 7 || lifts != 7 || active {
		t.Fatalf("contacts not cleanly released: starts=%d lifts=%d", starts, lifts)
	}
}
